def parse_amount(text):
    if not text or text.isspace():
        raise ValueError
    text = text.strip()
    if not text:
        raise ValueError
    # replace comma with dot for decimal
    if ',' in text and '.' in text:
        # ambiguous, reject
        raise ValueError
    if ',' in text:
        text = text.replace(',', '.')
    # allow only digits, dot, maybe leading minus? negative not allowed
    # simple conversion
    try:
        val = float(text)
    except ValueError:
        raise ValueError
    # reject negative and non-finite
    if val < 0:
        raise ValueError
    if not (val == val):  # nan
        raise ValueError
    if abs(val) == float('inf'):
        raise ValueError
    # zero is fine
    return val
